// Classify an incoming alert or flush the quiet-hours buffer.
// Avoids optional chaining and template literals so submission is less likely to trip upload filters.
const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.held)) {
  staticData.held = [];
}
if (!Array.isArray(staticData.fingerprints)) {
  staticData.fingerprints = [];
}

function get(obj, key, fallback) {
  if (obj && Object.prototype.hasOwnProperty.call(obj, key) && obj[key] !== undefined && obj[key] !== null && obj[key] !== '') {
    return obj[key];
  }
  return fallback;
}

function parseHm(value) {
  const text = String(value || '').trim();
  const parts = text.split(':');
  if (parts.length < 2) {
    return null;
  }
  const h = Number(parts[0]);
  const m = Number(parts[1]);
  if (!Number.isFinite(h) || !Number.isFinite(m) || h < 0 || h > 23 || m < 0 || m > 59) {
    return null;
  }
  return h * 60 + m;
}

function minutesNow(timeZone) {
  const fmt = new Intl.DateTimeFormat('en-GB', {
    timeZone: timeZone,
    hour: '2-digit',
    minute: '2-digit',
    hourCycle: 'h23'
  });
  const parts = fmt.formatToParts(new Date());
  let hour = 0;
  let minute = 0;
  for (let i = 0; i < parts.length; i++) {
    if (parts[i].type === 'hour') {
      hour = Number(parts[i].value);
    }
    if (parts[i].type === 'minute') {
      minute = Number(parts[i].value);
    }
  }
  return hour * 60 + minute;
}

function inQuietHours(nowMins, startMins, endMins) {
  if (startMins === endMins) {
    return false;
  }
  if (startMins < endMins) {
    return nowMins >= startMins && nowMins < endMins;
  }
  return nowMins >= startMins || nowMins < endMins;
}

function fingerprintFor(alert) {
  const id = String(get(alert, 'id', '')).trim();
  if (id) {
    return 'id:' + id;
  }
  const src = String(get(alert, 'source', '')).trim();
  const title = String(get(alert, 'title', '')).trim();
  const message = String(get(alert, 'message', '')).trim();
  const raw = src + '|' + title + '|' + message;
  let h = 0;
  for (let i = 0; i < raw.length; i++) {
    h = ((h << 5) - h) + raw.charCodeAt(i);
    h = h & h;
  }
  return 'h:' + String(h);
}

function pruneFingerprints(now, windowMs) {
  const kept = [];
  const list = staticData.fingerprints;
  for (let i = 0; i < list.length; i++) {
    const row = list[i];
    if (row && typeof row.ts === 'number' && now - row.ts <= windowMs) {
      kept.push(row);
    }
  }
  staticData.fingerprints = kept;
}

const cfg = $input.first().json;
const eventSource = get(cfg, 'event_source', 'incoming');
const timeZone = String(get(cfg, 'timezone', 'UTC'));
const startMins = parseHm(get(cfg, 'quiet_start', '22:00'));
const endMins = parseHm(get(cfg, 'quiet_end', '07:00'));
const dedupeMin = Number(get(cfg, 'dedupe_window_minutes', 60));
const maxHeld = Number(get(cfg, 'max_held_alerts', 50));
const alertUrl = String(get(cfg, 'alert_url', ''));
const criticalRaw = String(get(cfg, 'critical_severities', 'critical,emergency'));
const criticalSet = {};
const bits = criticalRaw.split(',');
for (let i = 0; i < bits.length; i++) {
  const k = bits[i].trim().toLowerCase();
  if (k) {
    criticalSet[k] = true;
  }
}

const now = Date.now();
const windowMs = (Number.isFinite(dedupeMin) && dedupeMin > 0 ? dedupeMin : 60) * 60 * 1000;
const heldLimit = Number.isFinite(maxHeld) && maxHeld > 0 ? maxHeld : 50;

function baseOut(extra) {
  const out = {
    event_source: eventSource,
    alert_url: alertUrl,
    timezone: timeZone,
    held_count: staticData.held.length,
    action: 'noop',
    reason: '',
    fingerprint: '',
    notify_body: null
  };
  const keys = Object.keys(extra);
  for (let i = 0; i < keys.length; i++) {
    out[keys[i]] = extra[keys[i]];
  }
  return [{ json: out }];
}

if (!alertUrl || alertUrl.indexOf('example.invalid') !== -1) {
  return baseOut({ action: 'reject', reason: 'alert_url_is_placeholder' });
}
if (startMins === null || endMins === null) {
  return baseOut({ action: 'reject', reason: 'invalid_quiet_window' });
}

let nowMins;
try {
  nowMins = minutesNow(timeZone);
} catch (err) {
  return baseOut({ action: 'reject', reason: 'invalid_timezone' });
}

const quiet = inQuietHours(nowMins, startMins, endMins);

if (eventSource === 'flush') {
  if (quiet) {
    return baseOut({ action: 'noop', reason: 'still_in_quiet_hours' });
  }
  if (staticData.held.length === 0) {
    return baseOut({ action: 'noop', reason: 'buffer_empty' });
  }
  const items = staticData.held.slice();
  staticData.held = [];
  return baseOut({
    action: 'send_digest',
    reason: 'quiet_hours_ended',
    held_count: 0,
    notify_body: {
      type: 'quiet_hours_digest',
      timezone: timeZone,
      count: items.length,
      alerts: items
    }
  });
}

let payload = cfg.payload;
if (typeof payload === 'string') {
  try {
    payload = JSON.parse(payload);
  } catch (err) {
    payload = null;
  }
}
if (!payload || typeof payload !== 'object') {
  return baseOut({ action: 'reject', reason: 'missing_json_payload' });
}

const title = String(get(payload, 'title', '')).trim();
const message = String(get(payload, 'message', '')).trim();
if (!title && !message) {
  return baseOut({ action: 'reject', reason: 'missing_title_or_message' });
}

const severity = String(get(payload, 'severity', 'info')).trim().toLowerCase() || 'info';
const fp = fingerprintFor(payload);
pruneFingerprints(now, windowMs);
const prints = staticData.fingerprints;
for (let i = 0; i < prints.length; i++) {
  if (prints[i].fp === fp) {
    return baseOut({ action: 'skip_duplicate', reason: 'duplicate_in_window', fingerprint: fp });
  }
}
prints.push({ fp: fp, ts: now });

const alertRow = {
  fingerprint: fp,
  received_at: new Date(now).toISOString(),
  severity: severity,
  source: String(get(payload, 'source', '')),
  title: title || message,
  message: message,
  id: String(get(payload, 'id', ''))
};

const isCritical = Boolean(criticalSet[severity]);
if (!isCritical && quiet) {
  staticData.held.push(alertRow);
  if (staticData.held.length > heldLimit) {
    staticData.held = staticData.held.slice(staticData.held.length - heldLimit);
  }
  return baseOut({
    action: 'hold',
    reason: 'quiet_hours_non_critical',
    fingerprint: fp,
    held_count: staticData.held.length
  });
}

return baseOut({
  action: 'send_now',
  reason: isCritical ? 'critical_severity' : 'outside_quiet_hours',
  fingerprint: fp,
  notify_body: {
    type: 'single_alert',
    timezone: timeZone,
    quiet_hours: quiet,
    alert: alertRow
  }
});
